<?php
require 'page-guard.php';require '../config/db_conn.php';require '../includes/school-year-schema.php';ensureSchoolYearRolloverSchema($conn);
if(!hash_equals($_SESSION['csrf_token']??'',$_POST['csrf_token']??'')){$_SESSION['toast']=['message'=>'The rollover request expired.','type'=>'error'];header('Location: school-year-rollover.php');exit;}
$admin=$conn->prepare('SELECT ADMIN_PASS FROM admins WHERE ADMIN_USER=? LIMIT 1');$admin->bind_param('s',$_SESSION['admin-user']);$admin->execute();$account=$admin->get_result()->fetch_assoc();if(!$account||!password_verify($_POST['current_password']??'',$account['ADMIN_PASS'])){$_SESSION['toast']=['message'=>'Administrator password is incorrect. No student records were changed.','type'=>'error'];header('Location: school-year-rollover-preview.php');exit;}
$setting=$conn->query('SELECT ACTIVE_SCHOOL_YEAR FROM school_year_settings WHERE ID=1')->fetch_assoc();$currentYear=$setting['ACTIVE_SCHOOL_YEAR']??'';$parts=array_map('intval',explode('-',$currentYear));if(count($parts)!==2){$_SESSION['toast']=['message'=>'Active school year is invalid.','type'=>'error'];header('Location: school-year-rollover.php');exit;}$nextYear=($parts[0]+1).'-'.($parts[1]+1);
$maps=[];$rows=$conn->query('SELECT * FROM school_year_rollover_maps');while($rows&&$map=$rows->fetch_assoc())$maps[$map['FROM_GRADE'].'|'.$map['FROM_STRAND'].'|'.$map['FROM_SECTION']]=$map;
$sources=[];$rows=$conn->query("SELECT GRADE,STRAND,SECTION FROM students WHERE ENROLLMENT_STATUS='Enrolled' AND GRADE BETWEEN 7 AND 11 GROUP BY GRADE,STRAND,SECTION");while($rows&&$source=$rows->fetch_assoc()){if(!isset($maps[$source['GRADE'].'|'.$source['STRAND'].'|'.$source['SECTION']])){$_SESSION['toast']=['message'=>'Every enrolled class must have a saved rollover mapping.','type'=>'error'];header('Location: school-year-rollover.php');exit;}$sources[]=$source;}
try{$conn->begin_transaction();$conn->query("UPDATE attendance a INNER JOIN students s ON TRIM(s.STUDENT_ID)=TRIM(a.STUDENT_ID) SET a.GRADE_SNAPSHOT=COALESCE(a.GRADE_SNAPSHOT,s.GRADE),a.STRAND_SNAPSHOT=IF(a.STRAND_SNAPSHOT='',s.STRAND,a.STRAND_SNAPSHOT),a.SECTION_SNAPSHOT=IF(a.SECTION_SNAPSHOT='',s.SECTION,a.SECTION_SNAPSHOT)");$archive=$conn->prepare('INSERT IGNORE INTO student_school_history (STUDENT_ID,SCHOOL_YEAR,GRADE,STRAND,SECTION,ENROLLMENT_STATUS) SELECT STUDENT_ID,?,?,?,?,ENROLLMENT_STATUS FROM students WHERE GRADE=? AND STRAND=? AND SECTION=? AND ENROLLMENT_STATUS=\'Enrolled\'');$promote=$conn->prepare('UPDATE students SET GRADE=?,STRAND=?,SECTION=? WHERE GRADE=? AND STRAND=? AND SECTION=? AND ENROLLMENT_STATUS=\'Enrolled\'');$moved=0;foreach($sources as $source){$map=$maps[$source['GRADE'].'|'.$source['STRAND'].'|'.$source['SECTION']];$grade=(int)$source['GRADE'];$strand=$source['STRAND'];$section=$source['SECTION'];$archive->bind_param('sississ',$currentYear,$grade,$strand,$section,$grade,$strand,$section);$archive->execute();$toGrade=(int)$map['TO_GRADE'];$toStrand=$map['TO_STRAND'];$toSection=$map['TO_SECTION'];$promote->bind_param('ississ',$toGrade,$toStrand,$toSection,$grade,$strand,$section);$promote->execute();$moved+=$promote->affected_rows;}$conn->query("INSERT IGNORE INTO student_school_history (STUDENT_ID,SCHOOL_YEAR,GRADE,STRAND,SECTION,ENROLLMENT_STATUS) SELECT STUDENT_ID,'$currentYear',GRADE,STRAND,SECTION,ENROLLMENT_STATUS FROM students WHERE GRADE=12 AND ENROLLMENT_STATUS='Enrolled'");$graduated=$conn->query("UPDATE students SET ENROLLMENT_STATUS='Graduated' WHERE GRADE=12 AND ENROLLMENT_STATUS='Enrolled'")->affected_rows;$update=$conn->prepare('UPDATE school_year_settings SET ACTIVE_SCHOOL_YEAR=? WHERE ID=1');$update->bind_param('s',$nextYear);$update->execute();$conn->commit();$_SESSION['toast']=['message'=>"School year rollover complete: $moved students promoted and $graduated Grade 12 students graduated.",'type'=>'success'];}catch(Throwable $error){$conn->rollback();$_SESSION['toast']=['message'=>'Rollover could not be completed. No student records were changed.','type'=>'error'];}
header('Location: school-year-rollover.php');exit;
